ANNOTATIONS("DESCRIPTION" 'Compliance frameworks (e.g. SOX, GDPR). Obligations belong to a framework.');

CREATE TABLE "PER_MST_COMPLIANCE_OBLIGATION" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "FRAMEWORK_UUID" NUMBER NOT NULL ENABLE,
  "PARENT_OBLIGATION_UUID" NUMBER,
  "OBLIGATION_REF" VARCHAR2(60) NOT NULL ENABLE,
  "OBLIGATION_TITLE" VARCHAR2(500) NOT NULL ENABLE,
  "OBLIGATION_TEXT" CLOB,
  "OBLIGATION_TYPE" VARCHAR2(30),
  "IS_MANDATORY" VARCHAR2(1) DEFAULT 'Y',
  "IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y',
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  "COMPLIANCE_STATUS" VARCHAR2(20) GENERATED ALWAYS AS (CASE WHEN ("IS_ACTIVE"='Y' AND "IS_MANDATORY"='Y') THEN 'Active' WHEN ("IS_ACTIVE"='Y' AND "IS_MANDATORY"='N') THEN 'Advisory' WHEN "IS_ACTIVE"='N' THEN 'Inactive' ELSE 'Draft' END) VIRTUAL,
  PRIMARY KEY ("UUID") ENABLE,
  CONSTRAINT "UQ_PMCO_REF" UNIQUE ("FRAMEWORK_UUID", "OBLIGATION_REF") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Compliance obligations register. WARNING: the status column is named COMPLIANCE_STATUS, not STATUS -- there is no column literally called STATUS on this table. This table also has NO due-date column of its own; "overdue" applies to GAPS against an obligation (see PER_TRN_COMPLIANCE_GAP.TARGET_CLOSURE_DATE), not the obligation record itself. For "overdue obligations" or "which obligations need attention" style questions, use PER_VW_COMPLIANCE_POSTURE instead, which pre-computes OPEN_GAPS and OVERDUE_GAPS per obligation.');

