  "APPROVED_BY" VARCHAR2(255),
  "APPROVED_ON" DATE,
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE,
  UNIQUE ("ACTION_REFERENCE") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'General action plans, often linked to incidents or corrective actions.');

CREATE TABLE "PER_TRN_ACTION_PLANS" (
  "UUID" NUMBER,
  "PLAN_REFERENCE" VARCHAR2(50) NOT NULL ENABLE,
