  "STATUS" VARCHAR2(50) DEFAULT 'OPEN',
  "PRIORITY" VARCHAR2(20) DEFAULT 'MEDIUM',
  "EVIDENCE_NOTES" CLOB,
  "APPROVAL_STATUS" VARCHAR2(50) DEFAULT 'DRAFT',
  "APPROVER_COMMENTS" CLOB,
  "CREATED_BY" VARCHAR2(200),
