  "ATTACHMENT" BLOB,
  "ATTACHMENT_MIME_TYPE" VARCHAR2(1020),
  "ATTACHMENT_NAME" VARCHAR2(1020),
  PRIMARY KEY ("UUID") ENABLE
);

CREATE TABLE "PER_TRN_ACTION_PLAN_TASK_LOG" (
  "UUID" NUMBER,
  "ACTION_PLAN_UUID" NUMBER NOT NULL ENABLE,
  "LOG_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,
  "WORK_DESCRIPTION" VARCHAR2(4000) NOT NULL ENABLE,
