  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Pending approval queue across the application: risks, controls, plans awaiting sign-off.');

CREATE TABLE "PER_TRN_COMPLIANCE_GAP" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "OBLIGATION_UUID" NUMBER NOT NULL ENABLE,
  "ASSESSMENT_CYCLE_UUID" NUMBER,
  "GAP_TITLE" VARCHAR2(300) NOT NULL ENABLE,
  "GAP_DESCRIPTION" CLOB,
  "CURRENT_STATE" CLOB,
  "TARGET_STATE" CLOB,
  "GAP_SEVERITY" VARCHAR2(20),
  "GAP_OWNER_UUID" NUMBER,
  "TARGET_CLOSURE_DATE" DATE,
  "ACTUAL_CLOSURE_DATE" DATE,
  "COMPLETION_PCT" NUMBER(3,0) DEFAULT 0,
  "STATUS" VARCHAR2(30) DEFAULT 'OPEN',
  "APPROVAL_STATUS" VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000),
  "APPROVED_BY" VARCHAR2(255),
  "APPROVED_ON" DATE,
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Compliance gaps via OBLIGATION_UUID = PER_MST_COMPLIANCE_OBLIGATION.UUID. This table has NO framework name column directly -- grouping by OBLIGATION_UUID alone shows a meaningless raw ID to the user. For "which framework has the most gaps" or any framework-level gap question, use PER_VW_COMPLIANCE_POSTURE instead, which already resolves FRAMEWORK_NAME and pre-counts OPEN_GAPS/OVERDUE_GAPS per obligation.');

CREATE TABLE "PER_TRN_COMPLIANCE_MAPPING" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "OBLIGATION_UUID" NUMBER NOT NULL ENABLE,
  "RISK_STATEMENT_UUID" NUMBER,
  "IDENTIFY_RISK_UUID" NUMBER,
  "CONTROL_UUID" NUMBER,
  "MAPPING_STRENGTH" VARCHAR2(20),
  "MAPPING_NOTES" VARCHAR2(2000),
  "IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y',
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Mapping table linking risks to compliance obligations. Use to answer which risks satisfy which obligations.');

CREATE TABLE "PER_TRN_CONTROL_IMPLEMENTATION" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "ROOT_CAUSE_UUID" NUMBER,
  "CONTROL_ID" NUMBER,
  "CONTROL_OWNER" NUMBER,
  "MITIGATION_TYPE" NUMBER,
  "CONTROL_FREQUENCY" NUMBER,
  "CONTROL_DESIGN_EFFECTIVENESS" NUMBER,
  "CONTROL_CLASIFICATION" NUMBER,
  "CONTROL_TYPE" NUMBER,
  "CONTROL_CATEGORY" NUMBER,
  "INHERENT_LIKELIHOOD" NUMBER,
  "RESIDUAL_LIKELIHOOD" NUMBER,
  "WEIGHTAGE_VALUE" NUMBER,
  "IS_STAGE_COMPLTED" CHAR(1),
  "IDENTIFY_RISK_UUID" NUMBER NOT NULL ENABLE,
  "ASSESSMENT_REFERENCE_NUMBER_UUID" NUMBER NOT NULL ENABLE,
  "APPROVAL_STATUS" VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000 CHAR),
  "APPROVED_BY" VARCHAR2(255 CHAR),
  "APPROVED_ON" DATE,
  "RISK_UUID" NUMBER,
  "EVIDENCE_NOTES" VARCHAR2(2000 CHAR),
  "CONTROL_EFFECTIVENESS_RATING" VARCHAR2(20 CHAR),
  "RESIDUAL_IMPACT" VARCHAR2(100),
  "RESIDUAL_RISK_SCORE" NUMBER(5,2),
  "CONTROL_RELATIONSHIP_TYPE" VARCHAR2(20) DEFAULT 'NEW' NOT NULL ENABLE,
  "PARENT_CONTROL_UUID" NUMBER,
  CONSTRAINT "PTCI_RELTYPE_CHK" CHECK (CONTROL_RELATIONSHIP_TYPE IN ('NEW','ENHANCEMENT','PROPOSED')) ENABLE,
  CONSTRAINT "PER_TRN_CONTROL_IMPLEMENTATION_PK" PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Controls per risk via IDENTIFY_RISK_UUID = PER_TRN_IDENTIFY_RISK.UUID. WARNING: both tables have their own UUID column -- do not SELECT T1.*, T2.* together. For any combined risk+control question, use PER_VW_RISK_360 instead, which is pre-joined with no ambiguity and includes CONTROL_EFFECTIVENESS_RATING, RESIDUAL_LIKELIHOOD/IMPACT/SCORE.');

CREATE TABLE "PER_TRN_IDENTIFY_RISK" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "IDENTIFY_RISK_UUID" NUMBER,
  "HIERARCHY_LEVEL" NUMBER,
  "HIERARCHY_NAME" NUMBER,
  "ASSESSMENT_REFERENCE_NUMBER" VARCHAR2(255 CHAR),
  "ASSESSMENT_REGISTERED_DATE" DATE,
  "ASSESSMENT_ACTUAL_START_DATE" DATE,
  "ASSESSMENT_ACTUAL_END_DATE" DATE,
  "BUSINESS_PROCESS_UUID" NUMBER,
  "BUSINESS_SUB_PROCESS_UUID" NUMBER,
  "RISK_TYPE_UUID" NUMBER,
  "RISK_STATEMENT_UUID" NUMBER,
  "IS_SOP_AVAILABLE" CHAR(1 CHAR),
  "INHERENT_SLE" NUMBER,
  "IS_STAGE_COMPLTED" CHAR(1 CHAR),
  "END_DATE" DATE,
  "START_DATE" DATE,
  "RISK_STATEMENT" VARCHAR2(4000),
  "RISK_TYPE" VARCHAR2(4000),
  "SUB_PROCESS_NAME" VARCHAR2(4000),
  "PROCESS_NAME" VARCHAR2(4000),
  "CREATED_ON" DATE,
  "RISK_CHAMPION_UUID" NUMBER,
  "STATUS" CHAR(1 CHAR),
  "APPROVAL_STATUS" VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000 CHAR),
  "APPROVED_BY" VARCHAR2(255 CHAR),
  "APPROVED_ON" DATE,
  "RISK_OWNER" VARCHAR2(500 CHAR),
  "RISK_CHAMPION" VARCHAR2(500 CHAR),
  "RISK_APPETITE" VARCHAR2(20 CHAR),
  "ASSESSMENT_CYCLE_UUID" NUMBER,
  "LAST_UPDATED_BY" VARCHAR2(100),
  "LAST_UPDATED_ON" DATE,
  "WORKFLOW_ID" NUMBER,
  CONSTRAINT "CK_IDR_SLE_NONNEG" CHECK (INHERENT_SLE IS NULL OR INHERENT_SLE >= 0) ENABLE NOVALIDATE,
  CONSTRAINT "CK_IDR_STAGE_FLAG" CHECK (IS_STAGE_COMPLTED IS NULL OR IS_STAGE_COMPLTED IN ('Y','N')) ENABLE NOVALIDATE,
  CONSTRAINT "CK_IDR_APPR_STATUS" CHECK (APPROVAL_STATUS IS NULL OR APPROVAL_STATUS IN ('DRAFT','SUBMITTED','APPROVED','REJECTED')) ENABLE NOVALIDATE,
  CONSTRAINT "PER_TRN_RISK_ASSESSMENT_PK" PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Risk register (one row per identified risk). TERM MAP: "department"/"business unit"/"division" = PROCESS_NAME. APPROVAL_STATUS is uppercase (APPROVED/DRAFT/SUBMITTED), compare case-insensitively. WARNING: this table AND PER_TRN_CONTROL_IMPLEMENTATION both have their own UUID column -- joining them with SELECT T1.*, T2.* causes an ambiguous-column error. For ANY question combining risks with their controls, use PER_VW_RISK_360 instead, which already joins them correctly with no ambiguity.');

CREATE TABLE "PER_TRN_IMPACT_CATEGORY" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "IMPACT_CATEGORY_UUID" NUMBER,
  "INHERENT_RISK_ASSESSMENT_UUID" NUMBER,
  "RISK_IMPACT_CATEGORY_UUID" NUMBER,
  "RISK_IMPACT_SUB_CATEGORY_UUID" NUMBER,
  "RISK_INHERENT_IMPACT_LEVEL" NUMBER,
  "RISK_RESIDUAL_IMPACT_LEVEL" NUMBER,
  CONSTRAINT "PER_TRN_IMPACT_CATEGORY_PK" PRIMARY KEY ("UUID") ENABLE
);

CREATE TABLE "PER_TRN_INCIDENT" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "INCIDENT_REFERENCE" VARCHAR2(50) NOT NULL ENABLE,
  "INCIDENT_TITLE" VARCHAR2(300) NOT NULL ENABLE,
  "INCIDENT_DESCRIPTION" CLOB,
  "INCIDENT_TYPE_UUID" NUMBER NOT NULL ENABLE,
  "SEVERITY_UUID" NUMBER NOT NULL ENABLE,
  "STATUS_UUID" NUMBER NOT NULL ENABLE,
  "RISK_UUID" NUMBER,
  "IDENTIFY_RISK_UUID" NUMBER,
  "ORG_HIERARCHY_UUID" NUMBER,
  "REPORTED_BY_UUID" NUMBER,
  "INCIDENT_OWNER_UUID" NUMBER,
  "REPORTED_ON" DATE DEFAULT SYSDATE NOT NULL ENABLE,
  "OCCURRED_ON" DATE,
  "DETECTED_ON" DATE,
  "TARGET_RESOLUTION_ON" DATE,
  "ACTUAL_RESOLUTION_ON" DATE,
  "ROOT_CAUSE_SUMMARY" CLOB,
  "CORRECTIVE_ACTION_SUMMARY" CLOB,
  "FINANCIAL_IMPACT" NUMBER(18,2),
  "CURRENCY_TYPE_UUID" NUMBER,
  "IS_SLA_BREACHED" VARCHAR2(1) DEFAULT 'N',
  "APPROVAL_STATUS" VARCHAR2(30) DEFAULT 'DRAFT' NOT NULL ENABLE,
  "APPROVER_COMMENTS" VARCHAR2(2000),
  "APPROVED_BY" VARCHAR2(255),
  "APPROVED_ON" DATE,
  "CREATED_BY" VARCHAR2(255),
  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE,
  UNIQUE ("INCIDENT_REFERENCE") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Incident log. WARNING: there is NO plain INCIDENT_TYPE text column on this table -- the type NAME only exists via JOIN: INCIDENT_TYPE_UUID = PER_MST_INCIDENT_TYPE.UUID, giving TYPE_NAME. Same pattern for SEVERITY_UUID -> PER_MST_INCIDENT_SEVERITY.SEVERITY_NAME and STATUS_UUID -> PER_MST_INCIDENT_STATUS.STATUS_NAME. FINANCIAL_IMPACT holds monetary loss. For ANY question combining incident type/severity/status with cost, count, or other detail, use PER_VW_INCIDENT_SUMMARY instead -- it already resolves all three names and computes RESOLUTION_DAYS and IS_OVERDUE.');

