  "CREATED_ON" DATE DEFAULT SYSDATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Corrective actions raised against incidents. Use for open/overdue corrective action questions.');

CREATE TABLE "PER_TRN_INHERENT_RISK_ASSESSMENT" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
