)
ANNOTATIONS("DESCRIPTION" 'Inherent risk assessment scores (impact x likelihood before controls) per risk per cycle.');

CREATE TABLE "PER_TRN_MITIGATION_PLANS" (
  "UUID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
