  "CREATED_ON" DATE,
  "UPDATED_BY" VARCHAR2(255),
  "UPDATED_ON" DATE,
  CONSTRAINT "PER_TRN_MITIGATION_PLANS_PK" PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Mitigation action plans for risks, with owner, target date and status.');

CREATE TABLE "PER_TRN_MITIGATION_PLAN_CONTROLS" (
  "UUID" NUMBER NOT NULL ENABLE,
