  CONSTRAINT "PER_TRN_RISK_MONITORING_PK" PRIMARY KEY ("UUID") ENABLE
)
ANNOTATIONS("DESCRIPTION" 'Ongoing monitoring records per risk via RISK_UUID = PER_TRN_IDENTIFY_RISK.UUID. A risk with no row here is not yet monitored.');

