CREATE TABLE "PER_USER_ROLE" (
  "USER_ROLE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "APP_USER_ID" NUMBER NOT NULL ENABLE,
  "ROLE_ID" NUMBER NOT NULL ENABLE,
  CONSTRAINT "PER_USER_ROLE_PK" PRIMARY KEY ("USER_ROLE_ID") ENABLE,
  CONSTRAINT "PER_USER_ROLE_UK" UNIQUE ("APP_USER_ID", "ROLE_ID") ENABLE
);

CREATE TABLE "PER_VENDOR" (
  "VENDOR_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "BUSINESS_KEY" VARCHAR2(20) NOT NULL ENABLE,
  "LEGAL_NAME" VARCHAR2(200) NOT NULL ENABLE,
  "TIER_CODE" VARCHAR2(10),
  "RESIDUAL_CODE" VARCHAR2(10),
  "DATA_CLASS_CODE" VARCHAR2(20),
  "OWNER_PERSON_ID" NUMBER,
  "CERTS" VARCHAR2(80),
  "SOURCE_SYSTEM" VARCHAR2(40),
  "SOURCE_KEY" VARCHAR2(80),
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp NOT NULL ENABLE,
  "CREATED_BY" VARCHAR2(80),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(80),
  "ROW_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
  CHECK (is_active in ('Y','N')) ENABLE,
  CONSTRAINT "PER_VENDOR_PK" PRIMARY KEY ("VENDOR_ID") ENABLE,
  UNIQUE ("BUSINESS_KEY") ENABLE
);

CREATE TABLE "PER_VENDOR_ASSESS" (
  "ASSESS_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "VENDOR_ID" NUMBER NOT NULL ENABLE,
  "INHERENT_CODE" VARCHAR2(10),
  "RESIDUAL_CODE" VARCHAR2(10),
  "ASSESSED_ON" DATE,
  CONSTRAINT "PER_VASS_PK" PRIMARY KEY ("ASSESS_ID") ENABLE
);

CREATE TABLE "PER_VENDOR_EXIT" (
  "EXIT_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "VENDOR_ID" NUMBER NOT NULL ENABLE,
  "REASON_TEXT" VARCHAR2(400),
  "ACCESS_KILLED_ON" DATE,
  "DATA_RETURNED_FLAG" CHAR(1) DEFAULT 'N',
  CHECK (data_returned_flag in ('Y','N')) ENABLE,
  CONSTRAINT "PER_VEXIT_PK" PRIMARY KEY ("EXIT_ID") ENABLE
);

CREATE TABLE "PER_VRM_DECISION" (
  "DECISION_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "VENDOR_ID" NUMBER NOT NULL ENABLE,
  "OUTCOME_CODE" VARCHAR2(20),
  "COMMITTEE_ON" DATE,
  "NOTE_TEXT" VARCHAR2(400),
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp NOT NULL ENABLE,
  "CREATED_BY" VARCHAR2(80),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(80),
  "ROW_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
  CHECK (is_active in ('Y','N')) ENABLE,
  CONSTRAINT "PER_VDEC_PK" PRIMARY KEY ("DECISION_ID") ENABLE
);

CREATE TABLE "PER_WEBHOOK_SUB" (
  "WEBHOOK_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "CONNECTION_ID" NUMBER NOT NULL ENABLE,
  "EVENT_NAME" VARCHAR2(80),
  "ORDS_PATH" VARCHAR2(200),
  "SECRET_CREDENTIAL_STATIC_ID" VARCHAR2(80),
  "ENABLED_FLAG" CHAR(1) DEFAULT 'N',
  CHECK (enabled_flag in ('Y','N')) ENABLE,
  CONSTRAINT "PER_WH_PK" PRIMARY KEY ("WEBHOOK_ID") ENABLE
);

CREATE TABLE "PER_WF_DEF" (
  "WF_DEF_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "CODE" VARCHAR2(40) NOT NULL ENABLE,
  "NAME" VARCHAR2(120) NOT NULL ENABLE,
  "MODULE_CODE" VARCHAR2(30),
  "CURRENT_VERSION_NO" NUMBER DEFAULT 1,
  "APEX_WORKFLOW_STATIC_ID" VARCHAR2(80),
  "STATUS_CODE" VARCHAR2(20),
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp NOT NULL ENABLE,
  "CREATED_BY" VARCHAR2(80),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(80),
  "ROW_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
  CHECK (is_active in ('Y','N')) ENABLE,
  CONSTRAINT "PER_WFDEF_PK" PRIMARY KEY ("WF_DEF_ID") ENABLE,
  UNIQUE ("CODE") ENABLE
);

CREATE TABLE "PER_WF_EDGE" (
  "WF_EDGE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "WF_VERSION_ID" NUMBER NOT NULL ENABLE,
  "FROM_NODE_KEY" VARCHAR2(40) NOT NULL ENABLE,
  "TO_NODE_KEY" VARCHAR2(40) NOT NULL ENABLE,
  "CONDITION_EXPR" VARCHAR2(400),
  CONSTRAINT "PER_WFEDGE_PK" PRIMARY KEY ("WF_EDGE_ID") ENABLE
);

CREATE TABLE "PER_WF_NODE" (
  "WF_NODE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "WF_VERSION_ID" NUMBER NOT NULL ENABLE,
  "NODE_KEY" VARCHAR2(40) NOT NULL ENABLE,
  "KIND_CODE" VARCHAR2(20) NOT NULL ENABLE,
  "NAME" VARCHAR2(80),
  "ASSIGNEE_ROLE_ID" NUMBER,
  "SLA_HOURS" NUMBER,
  "POS_X" NUMBER,
  "POS_Y" NUMBER,
  CONSTRAINT "PER_WFNODE_PK" PRIMARY KEY ("WF_NODE_ID") ENABLE
);

CREATE TABLE "PER_WF_VERSION" (
  "WF_VERSION_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "WF_DEF_ID" NUMBER NOT NULL ENABLE,
  "VERSION_NO" NUMBER NOT NULL ENABLE,
  "BPMN_JSON" JSON,
  "COMMENT_TEXT" VARCHAR2(400),
  "PUBLISHED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  "PUBLISHED_BY" VARCHAR2(80),
  CONSTRAINT "PER_WFVER_PK" PRIMARY KEY ("WF_VERSION_ID") ENABLE,
  CONSTRAINT "PER_WFVER_UK" UNIQUE ("WF_DEF_ID", "VERSION_NO") ENABLE
);

CREATE TABLE "PXT_AI_ALLOWED_OBJECT" (
  "OBJECT_NAME" VARCHAR2(128) NOT NULL ENABLE,
  "LABEL" VARCHAR2(200),
  "IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y',
  "ADDED_ON" TIMESTAMP (6) DEFAULT systimestamp,
  "ADDED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_ALLOWED_OBJECT_PK" PRIMARY KEY ("OBJECT_NAME") ENABLE,
  CONSTRAINT "PXT_AI_ALLOWED_OBJECT_CK1" CHECK (is_active in ('Y','N')) ENABLE
);

CREATE TABLE "PXT_AI_CONFIG" (
  "CONFIG_ID" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ENABLED" VARCHAR2(1) DEFAULT 'Y',
  "ENGINE_CODE" VARCHAR2(30) DEFAULT 'SELECT_AI',
  "AI_PROFILE" VARCHAR2(128),
  "MODEL_NAME" VARCHAR2(128),
  "MAX_ROWS" NUMBER DEFAULT 500,
  "STMT_TIMEOUT" NUMBER DEFAULT 30,
  "ALLOW_SCOPE" VARCHAR2(20) DEFAULT 'VIEWS',
  "ACCENT_FROM" VARCHAR2(9) DEFAULT '#7C3AED',
  "ACCENT_TO" VARCHAR2(9) DEFAULT '#06B6D4',
  "GREETING" VARCHAR2(400) DEFAULT 'Hi! Ask me anything about your GRC data - risks, audits, incidents, compliance, vendors. I can chart it or export to Excel, CSV, PDF or Word.',
  "HISTORY_LIMIT" NUMBER DEFAULT 20,
  "UPDATED_ON" TIMESTAMP (6) DEFAULT systimestamp,
  "UPDATED_BY" VARCHAR2(255),
  "RAG_MODE" VARCHAR2(10) DEFAULT 'RAG',
  "NARRATIVE_YN" CHAR(1) DEFAULT 'Y',
  "EMBED_PARAMS" VARCHAR2(2000),
  "VECTOR_PROVIDER" VARCHAR2(100) DEFAULT 'pericope_embed',
  "CHUNK_WORDS" NUMBER DEFAULT 220,
  "CHUNK_OVERLAP" NUMBER DEFAULT 22,
  "INDEX_DOCUMENTS" CHAR(1) DEFAULT 'Y',
  "INDEX_FILES" CHAR(1) DEFAULT 'Y',
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  "CREATED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_CONFIG_PK" PRIMARY KEY ("CONFIG_ID") ENABLE,
  CONSTRAINT "PXT_AI_CONFIG_CK1" CHECK (is_enabled in ('Y','N')) ENABLE,
  CONSTRAINT "PXT_AI_CONFIG_CK2" CHECK (allow_scope in ('LIST','VIEWS','ALL')) ENABLE
);

CREATE TABLE "PXT_AI_CONVERSATION" (
  "CONVERSATION_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "APEX_USER" VARCHAR2(255),
  "PERSON_ID" NUMBER,
  "TITLE" VARCHAR2(200),
  "STARTED_ON" TIMESTAMP (6) DEFAULT systimestamp,
  "IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y',
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  "CREATED_BY" VARCHAR2(255),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_CONVERSATION_PK" PRIMARY KEY ("CONVERSATION_ID") ENABLE
);

CREATE TABLE "PXT_AI_ENGINE" (
  "ENGINE_CODE" VARCHAR2(30) NOT NULL ENABLE,
  "SEQ" NUMBER,
  "LABEL" VARCHAR2(80),
  "PROVIDER" VARCHAR2(30),
  "PROVIDER_ENDPOINT" VARCHAR2(200),
  "ACL_HOST" VARCHAR2(200),
  "CREDENTIAL_NAME" VARCHAR2(128),
  "PROFILE_NAME" VARCHAR2(128),
  "MODEL_NAME" VARCHAR2(200),
  "API_KEY" VARCHAR2(500),
  "IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y',
  "FREE_NOTE" VARCHAR2(240),
  "UPDATED_ON" TIMESTAMP (6),
  "UPDATED_BY" VARCHAR2(255),
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  "CREATED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_ENGINE_PK" PRIMARY KEY ("ENGINE_CODE") ENABLE,
  CONSTRAINT "PXT_AI_ENGINE_CK1" CHECK (is_active in ('Y','N')) ENABLE
);

CREATE TABLE "PXT_AI_MESSAGE" (
  "MESSAGE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "CONVERSATION_ID" NUMBER,
  "SEQ" NUMBER,
  "ROLE" VARCHAR2(10),
  "PROMPT_TEXT" CLOB,
  "SQL_TEXT" CLOB,
  "NARRATIVE" CLOB,
  "ROW_COUNT" NUMBER,
  "STATUS" VARCHAR2(20),
  "ERR_TEXT" VARCHAR2(4000),
  "CHART_TYPE" VARCHAR2(20) DEFAULT 'TABLE',
  "LABEL_COL" VARCHAR2(128),
  "VALUE_COL" VARCHAR2(128),
  "APEX_USER" VARCHAR2(255),
  "CREATED_ON" TIMESTAMP (6) DEFAULT systimestamp,
  "CREATED_BY" VARCHAR2(255),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_MESSAGE_PK" PRIMARY KEY ("MESSAGE_ID") ENABLE,
  CONSTRAINT "PXT_AI_MESSAGE_CK1" CHECK (role in ('USER','AGENT')) ENABLE
);

CREATE TABLE "PXT_AI_QUERY_LOG" (
  "LOG_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "APEX_USER" VARCHAR2(255),
  "QUESTION" VARCHAR2(4000),
  "SQL_TEXT" CLOB,
  "STATUS" VARCHAR2(20),
  "ROW_COUNT" NUMBER,
  "MS" NUMBER,
  "CREATED_ON" TIMESTAMP (6) DEFAULT systimestamp,
  "CREATED_BY" VARCHAR2(255),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(255),
  CONSTRAINT "PXT_AI_QUERY_LOG_PK" PRIMARY KEY ("LOG_ID") ENABLE
);

CREATE TABLE "PXT_APP_USER" (
  "APP_USER_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "PERSON_ID" NUMBER,
  "APEX_USERNAME" VARCHAR2(100) NOT NULL ENABLE,
  "STATUS_CODE" VARCHAR2(20) NOT NULL ENABLE,
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp NOT NULL ENABLE,
  "CREATED_BY" VARCHAR2(80),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(80),
  "ROW_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
  "DISPLAY_NAME" VARCHAR2(120),
  "EMAIL" VARCHAR2(200),
  CONSTRAINT "PXT_APP_USER_PK" PRIMARY KEY ("APP_USER_ID") ENABLE,
  CONSTRAINT "PXT_APP_USER_CK1" CHECK (is_active in ('Y','N')) ENABLE,
  CONSTRAINT "PXT_APP_USER_UK" UNIQUE ("APEX_USERNAME") ENABLE
);

CREATE TABLE "PXT_PERSON" (
  "PERSON_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "DISPLAY_NAME" VARCHAR2(120) NOT NULL ENABLE,
  "EMAIL" VARCHAR2(200) NOT NULL ENABLE,
  "TITLE" VARCHAR2(80),
  "LOD_CODE" VARCHAR2(10) NOT NULL ENABLE,
  "SOURCE_SYSTEM" VARCHAR2(40),
  "SOURCE_KEY" VARCHAR2(80),
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp NOT NULL ENABLE,
  "CREATED_BY" VARCHAR2(80),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE,
  "UPDATED_BY" VARCHAR2(80),
  "ROW_VERSION" NUMBER DEFAULT 1 NOT NULL ENABLE,
  "IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
  CONSTRAINT "PXT_PERSON_PK" PRIMARY KEY ("PERSON_ID") ENABLE,
  CONSTRAINT "PXT_PERSON_CK1" CHECK (is_active in ('Y','N')) ENABLE,
  CONSTRAINT "PERSON_TUK" UNIQUE ("EMAIL") ENABLE
);

CREATE TABLE "PXT_PLUGIN_CONFIG" (
  "CONFIG_KEY" VARCHAR2(100) NOT NULL ENABLE,
  "CONFIG_VALUE" VARCHAR2(4000),
  "DESCRIPTION" VARCHAR2(400),
  "UPDATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  "UPDATED_BY" VARCHAR2(255) DEFAULT nvl(sys_context('APEX$SESSION','APP_USER'), user),
  CONSTRAINT "PXT_PLUGIN_CONFIG_PK" PRIMARY KEY ("CONFIG_KEY") ENABLE
);

CREATE TABLE "PXT_PLUGIN_LOG" (
  "LOG_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "PLUGIN_CODE" VARCHAR2(40),
  "ACTION_CODE" VARCHAR2(40),
  "MODULE_CODE" VARCHAR2(40),
  "OBJECT_TYPE" VARCHAR2(60),
  "OBJECT_KEY" VARCHAR2(100),
  "DETAIL" VARCHAR2(4000),
  "LOGGED_BY" VARCHAR2(255) DEFAULT nvl(sys_context('APEX$SESSION','APP_USER'), user),
  "LOGGED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  PRIMARY KEY ("LOG_ID") ENABLE
);

CREATE TABLE "PXT_PLUGIN_NOTICE" (
  "NOTICE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "PERSON_ID" NUMBER,
  "MODULE_CODE" VARCHAR2(40),
  "OBJECT_KEY" VARCHAR2(100),
  "TITLE" VARCHAR2(400),
  "BODY" VARCHAR2(4000),
  "KIND_CODE" VARCHAR2(20) DEFAULT 'INFO',
  "LINK_URL" VARCHAR2(1000),
  "IS_READ" VARCHAR2(1) DEFAULT 'N',
  "CREATED_ON" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT systimestamp,
  CHECK (is_read in ('Y','N')) ENABLE,
  PRIMARY KEY ("NOTICE_ID") ENABLE
);

CREATE TABLE "WF_DEBUG_LOG" (
  "ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL ENABLE,
  "CREATED_ON" TIMESTAMP (6) DEFAULT SYSTIMESTAMP,
  "MSG" VARCHAR2(4000)
);
